const props = link.properties || {};
const actionLink = props.action_link || \"\";
console.log(\"5.GENERATE_LINK=OK verification_type=\" + (props.verification_type || \"classic\"));
console.log(\"   redirect_to=\" + (props.redirect_to || \"(embedded)\"));
console.log(\"   action_link params: \" + [...actionLink.split(\"?\")[1].split(\"&\")].map(p => p.split(\"=\")[0] + \"=\" + (p.split(\"=\")[0] === \"redirect_to\" ? decodeURIComponent(p.split(\"=\")[1] || \"\") : \"<redacted>\")).join(\" \"));
require(\"fs\").writeFileSync(\"/tmp/recovery-link.txt\", actionLink);
" "$SURL" "$ANON" "$ROLE" "$QA" "$OLDPW" 2>&1 | tail -12
'

