await page.waitForSelector(\"#form-section:not(.hidden)\", { timeout: 25000 });
console.log(\"3.NEW_PASSWORD_FORM=VISIBLE (live production page accepted real recovery session)\");
console.log(\"   EMAIL_CHIP=\" + ((await page.textContent(\"#email-value\")) || \"\").trim());

// password validation on the live page
await page.fill(\"#new-password\", \"weak\");
await page.fill(\"#confirm-password\", \"weak\");
await page.click(\"#submit-btn\");
await page.waitForSelector(\".status.error\", { timeout: 5000 });
console.log(\"4.WEAK_PASSWORD_REJECTED=\" + ((await page.textContent(\".status\")) || \"\").trim().slice(0,72));

// real password update on the live production page
await page.fill(\"#new-password\", newPw);
await page.fill(\"#confirm-password\", newPw);
await page.click(\"#submit-btn\");
await page.waitForSelector(\"#success-section:not(.hidden)\", { timeout: 20000 });
console.log(\"5.PASSWORD_UPDATED=OK (\" + ((await page.textContent(\"#success-section h1\")) || \"\").trim() + \")\");
await browser.close();

