console.log(\"6.NEW_PASSWORD_LOGIN=\" + (newErr ? \"FAIL \" + newErr.message : \"OK(200)\"));
const { error: oldErr } = await pub.auth.signInWithPassword({ email: qaEmail, password: \"IvxAut0-Reset-Old1\" });
